# Compute likelihood for line 2 data under each triplet and scenario
import numpy as np
from scipy.stats import norm

df_line2 = df[df['line']==2].copy()
triplets = [(3.4, 2.25), (3.8, 2.0)]
scenarios = ['maintain', 'revise', 'doubt']
noise_base = 0.65
noise_high_slope = 0.22
gain = 11.5
initial_region_max = 6.0
activation_end = 10.0

def phi(d):
    if d <= initial_region_max:
        return 0.0
    elif d >= activation_end:
        return 1.0
    else:
        t = (d - initial_region_max) / (activation_end - initial_region_max)
        return t*t*(3 - 2*t)

def base_mean(drv, scale):
    return 10.0 + gain * (1.0 - np.exp(-drv / scale))

def base_sd(drv):
    return noise_base + noise_high_slope * max(drv - 5.0, 0.0)

ll = {}
for scale, amplitude in triplets:
    for scen in scenarios:
        loglik = 0.0
        for _, row in df_line2.iterrows():
            d = row['driver']
            mu = base_mean(d, scale)
            sigma = base_sd(d)
            if scen == 'revise':
                mu -= amplitude * phi(d)
            elif scen == 'doubt':
                # mixture of two normals with equal weight
                # loglik = log(0.5 * N(y|mu + a*phi, sigma) + 0.5 * N(y|mu - a*phi, sigma))
                lp1 = norm.logpdf(row['outcome'], mu + amplitude * phi(d), sigma)
                lp2 = norm.logpdf(row['outcome'], mu - amplitude * phi(d), sigma)
                loglik += np.log(0.5 * np.exp(lp1) + 0.5 * np.exp(lp2))
                continue
            # maintain (or revise already adjusted)
            loglik += norm.logpdf(row['outcome'], mu, sigma)
        ll[(scale, amplitude, scen)] = loglik
        print(f"scale {scale}, amplitude {amplitude}, scenario {scen}: loglik = {loglik:.2f}")

# Compute posterior given prior: triplet weights (0.5987,0.4013) and scenario prior (0.84,0.08,0.08)
prior_triplet = [0.5987108427646576, 0.40128915723534236]
prior_scen = {'maintain':0.84, 'revise':0.08, 'doubt':0.08}
# Combine
best_key = max(ll, key=ll.get)
print(f"\nBest combination: {best_key} with loglik {ll[best_key]:.2f}")

# Compute phi for drivers
def phi(d):
    if d <= 6.0:
        return 0.0
    elif d >= 10.0:
        return 1.0
