def base_sd(drv):
    return noise_base + noise_high_slope * max(drv - 5.0, 0.0)

# Panel data
panel_line2 = panel[panel['line']==2].copy()
ll_panel = {}
for scale, amplitude in triplets:
    for scen in scenarios:
        loglik = 0.0
        for _, row in panel_line2.iterrows():
            d = row['driver']
            s = row['diagnostic_stratum']
            mu = base_mean(d, scale)
            sigma = base_sd(d)
            phi_val = phi(d)
            if scen == 'maintain':
                # no shift for either stratum
                pass
            elif scen == 'revise':
                mu -= amplitude * phi_val
            elif scen == 'doubt':
                mu += s * amplitude * phi_val  # s is -1 or 1
            loglik += norm.logpdf(row['outcome'], mu, sigma)
        ll_panel[(scale, amplitude, scen)] = loglik
        print(f"Panel: scale {scale}, amp {amplitude}, scen {scen}: loglik = {loglik:.2f}")

# Combine with prefix likelihood (prefix likelihood independent of scenario because phi=0)
