ll_prefix = {}
for scale, amplitude in triplets:
    loglik = 0.0
    for _, row in df.iterrows():
        d = row['driver']
        mu = base_mean(d, scale)
        sigma = base_sd(d)
        loglik += norm.logpdf(row['outcome'], mu, sigma)
    ll_prefix[(scale, amplitude)] = loglik
    print(f"Prefix: scale {scale}, amp {amplitude}: loglik = {loglik:.2f}")

# Compute total loglik for each triplet-scenario combination
total_ll = {}
for scale, amplitude in triplets:
    for scen in scenarios:
        total = ll_prefix[(scale, amplitude)] + ll_panel[(scale, amplitude, scen)]
        total_ll[(scale, amplitude, scen)] = total
        print(f"Total: scale {scale}, amp {amplitude}, scen {scen}: total loglik = {total:.2f}")

# Compute posterior probabilities using prior weights
prior_triplet = [0.5987108427646576, 0.40128915723534236]
prior_scen = {'maintain':0.84, 'revise':0.08, 'doubt':0.08}
# unnormalized posterior = prior * exp(ll)
post = {}
for (scale,amp,scen), ll in total_ll.items():
    prior = prior_triplet[0] if scale==3.4 else prior_triplet[1]
    prior *= prior_scen[scen]
    post[(scale,amp,scen)] = prior * np.exp(ll)
# normalize
Z = sum(post.values())
for key in post:
    post[key] /= Z
    print(f"Posterior {key}: {post[key]:.4f}")

# Sum over triplets to get scenario posterior
scen_post = {'maintain':0, 'revise':0, 'doubt':0}
for (scale,amp,scen), prob in post.items():
