import pandas as pd
import numpy as np

def model(regime, n, seed):
    rng = np.random.RandomState(seed)
    line = regime.config.get('line')
    driver = regime.config.get('driver')
    # Fixed parameters from inference
    gain = 11.5
    scale = 3.8
    amplitude = 2.0
    scenario = 'revise'  # certain from data
    noise_base = 0.65
    noise_high_slope = 0.22
    initial_region_max = 6.0
    activation_end = 10.0

    def phi(d):
        if d <= initial_region_max:
            return 0.0
        elif d >= activation_end:
            return 1.0
        else:
            t = (d - initial_region_max) / (activation_end - initial_region_max)
            return t*t*(3 - 2*t)

    def base_mean(drv):
        return 10.0 + gain * (1.0 - np.exp(-drv / scale))

    def base_sd(drv):
        return noise_base + noise_high_slope * max(drv - 5.0, 0.0)

    target_line = 2
    is_target = (line == target_line)

    outcomes = np.zeros(n)
    for i in range(n):
        mu = base_mean(driver)
        sigma = base_sd(driver)
        if is_target:
            phi_val = phi(driver)
            # revise scenario subtracts amplitude*phi
            mu -= amplitude * phi_val
        outcomes[i] = rng.normal(mu, sigma)
    return pd.DataFrame({'outcome': outcomes})
